from functools import wraps
import taf.ul.sc.tl_config as tl_config
from taf.ul.sc.util.helpers import is_dry_run


def web_connection_decorator(web_fun):
    @wraps(web_fun)
    def wrapper(self, *args, **kwargs):
        self.connect_to_webui()
        try:
            result = web_fun(self, *args, **kwargs)
            return result
        finally:
            self.disconnect_webui()

    return wrapper


class GenericOAM(object):
    def __init__(self, oam_ip, mrbts_id=None, nrbts_id=None):
        self.connection = None
        self.oam_ip = oam_ip
        self.mrbts_id = mrbts_id
        self.nrbts_id = nrbts_id
        if not is_dry_run():
            if hasattr(tl_config.tl, "gnbs") and tl_config.tl.gnbs:
                if not self.mrbts_id:
                    self.mrbts_id = tl_config.tl.gnbs[0].instance_id
                if not self.nrbts_id:
                    self.nrbts_id = tl_config.tl.gnbs[0].global_bts_id
            else:
                if not self.mrbts_id:
                    self.mrbts_id = tl_config.tl.enbs[0].instance_id
                if not self.nrbts_id:
                    self.nrbts_id = tl_config.tl.enbs[0].global_bts_id

    @web_connection_decorator
    def get_sw_version(self):
        """
        Get software version.

        :return: software version.
        """
        sw_version = self.connection.get_sw_version()
        return sw_version

    @web_connection_decorator
    def get_active_alarms_list(self):
        """
        Get list of alarms active on the AirScale.

        :return: list of active alarms
        """
        return self.connection.get_active_alarms()

    @web_connection_decorator
    def get_historic_alarms_list(self):
        """
        Get list of historic alarms on the AirScale.

        :return: list of history alarms
        """
        return self.connection.get_historic_alarms(timeout=60)

    @web_connection_decorator
    def perform_commissioning(self, scf_xml, **kwargs):
        """
        Update configuration on the AirScale using given scf file.
        :param scf_xml: configuration file
        :return: None for megazone_client, commissioning status for cOAM
        """
        return self.connection.perform_commissioning(scf_file=scf_xml, **kwargs)

    @web_connection_decorator
    def get_commissioning_file_content(self):
        """
        Get current configuration.

        :return: None
        """
        return self.connection.get_current_scf_content(timeout=120)
